+using System.ComponentModel;
+using Microsoft.Agents.AI;
+using Microsoft.Extensions.AI;
+using Microsoft.Extensions.DependencyInjection;
+using OpenAI;
+
+// --- Configuration ---
+var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
+    ?? throw new InvalidOperationException(
+        "Set the OPENAI_API_KEY environment variable to run this app.");
+
+const string modelId = "gpt-4o-mini-2024-07-18";
+
+// --- DI container setup ---
+var services = new ServiceCollection();
+
+services.AddChatClient(builder => builder
+    .UseOpenAIChatClient(modelId, new OpenAIClientOptions
+    {
+        Endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL") is { Length: > 0 } url
+            ? new Uri(url)
+            : null,
+    }, apiKey));
+
+var sp = services.BuildServiceProvider();
+var chatClient = sp.GetRequiredService<IChatClient>();
+
+// --- Tools ---
+var tools = new AITool[]
+{
+    AIFunctionFactory.Create(ResearchTools.SearchWeb),
+    AIFunctionFactory.Create(ResearchTools.SaveNote),
+    AIFunctionFactory.Create(ResearchTools.GetNotes),
+};
+
+// --- Agent setup ---
+var agent = new ChatClientAgent(
+    chatClient,
+    instructions: """
+        You are a research assistant. Your job is to research a topic thoroughly by:
+        1. Searching the web for relevant information (make multiple searches with different queries)
+        2. Saving important findings as notes
+        3. After gathering enough information, reviewing your notes and providing a comprehensive summary
+
+        Always search at least 2-3 different queries to get diverse perspectives.
+        Save key facts as notes before summarizing.
+        End with a well-structured summary of your findings.
+        """,
+    name: "ResearchAgent",
+    description: "An agent that researches topics using web search and note-taking",
+    tools: tools);
+
+// --- Run the agent ---
+Console.WriteLine("=== Research Agent ===");
+Console.Write("Enter a topic to research: ");
+var topic = Console.ReadLine()?.Trim();
+
+if (string.IsNullOrEmpty(topic))
+{
+    Console.WriteLine("No topic provided. Exiting.");
+    return;
+}
+
+Console.WriteLine($"\nResearching: {topic}\n");
+Console.WriteLine(new string('-', 50));
+
+var session = await agent.CreateSessionAsync(conversationId: "research-session");
+
+var response = await agent.RunAsync(
+    $"Please research the following topic and provide a comprehensive summary: {topic}",
+    session,
+    cancellationToken: CancellationToken.None);
+
+Console.WriteLine("\n" + new string('=', 50));
+Console.WriteLine("RESEARCH SUMMARY");
+Console.WriteLine(new string('=', 50));
+Console.WriteLine(response.Text);
+
+// --- Tool implementations ---
+public static class ResearchTools
+{
+    private static readonly List<string> _notes = [];
+    private static readonly HttpClient _httpClient = new();
+
+    [Description("Search the web for information on a given query. Returns search result snippets.")]
+    public static async Task<string> SearchWeb(
+        [Description("The search query to look up")] string query)
+    {
+        Console.WriteLine($"  🔍 Searching: \"{query}\"");
+
+        try
+        {
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+            var json = await _httpClient.GetStringAsync(url);
+
+            var doc = System.Text.Json.JsonDocument.Parse(json);
+            var root = doc.RootElement;
+
+            var results = new List<string>();
+
+            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstractText)
+                results.Add($"Summary: {abstractText}");
+
+            if (root.TryGetProperty("RelatedTopics", out var topics))
+            {
+                foreach (var item in topics.EnumerateArray().Take(5))
+                {
+                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
+                        results.Add($"- {t}");
+                }
+            }
+
+            if (results.Count == 0)
+                return $"No detailed results found for '{query}'. Try a more specific or different query.";
+
+            return string.Join("\n", results);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
+
+    [Description("Save a research note for later reference. Use this to record important findings.")]
+    public static string SaveNote(
+        [Description("The note content to save")] string note,
+        [Description("A short label/category for the note")] string label)
+    {
+        _notes.Add($"[{label}] {note}");
+        Console.WriteLine($"  📝 Note saved: [{label}] {(note.Length > 60 ? note[..60] + "..." : note)}");
+        return $"Note saved successfully. You now have {_notes.Count} note(s).";
+    }
+
+    [Description("Retrieve all saved research notes to review before writing a summary.")]
+    public static string GetNotes()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        Console.WriteLine($"  📋 Reviewing {_notes.Count} note(s)");
+        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
+    }
+}
